#include <stdio.h>
int main(void){int n,bt[100],pr[100],p[100],wt[100],tat[100],i,j,t;float aw=0,at=0;printf("Number of processes: ");scanf("%d",&n);if(n<1||n>100)return 1;for(i=0;i<n;i++){printf("Burst and priority for P%d (higher value = higher priority): ",i+1);scanf("%d%d",&bt[i],&pr[i]);p[i]=i+1;}for(i=0;i<n;i++)for(j=i+1;j<n;j++)if(pr[j]>pr[i]){t=pr[i];pr[i]=pr[j];pr[j]=t;t=bt[i];bt[i]=bt[j];bt[j]=t;t=p[i];p[i]=p[j];p[j]=t;}wt[0]=0;for(i=1;i<n;i++)wt[i]=wt[i-1]+bt[i-1];printf("PID\tBT\tPR\tWT\tTAT\n");for(i=0;i<n;i++){tat[i]=wt[i]+bt[i];aw+=wt[i];at+=tat[i];printf("P%d\t%d\t%d\t%d\t%d\n",p[i],bt[i],pr[i],wt[i],tat[i]);}printf("Avg WT=%.2f Avg TAT=%.2f\n",aw/n,at/n);}